import {planCatalog,plansForRole} from './pricing-catalog.mjs';
import {accountReturnTo} from './account-journey.mjs';
import {contactTopics} from './contact-catalog.mjs';
import {storePlatforms} from './store-platform-catalog.mjs';
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const logo='<a class="brand" href="/" aria-label="Affimaro home"><span class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M8 22V13a8 8 0 0 1 16 0v9M8 17h16M16 17v8"/></svg></span><span>affimaro<span class="brand-period">.</span></span></a>';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,href,kind='dark')=>`<a class="btn btn-${kind}" href="${href}">${label}${icon('arrow')}</a>`;
const intro=(eyebrow,title,text)=>`<div class="m-section-heading"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${text}</p></div>`;
const featureCards=items=>`<div class="m-card-grid">${items.map(([symbol,title,text,href])=>`<article class="m-feature-card"><span class="m-feature-icon">${icon(symbol)}</span><h3>${title}</h3><p>${text}</p>${href?`<a class="text-link" href="${href}">Explore ${title.toLowerCase()}${icon('arrow')}</a>`:''}</article>`).join('')}</div>`;
const steps=items=>`<ol class="m-process">${items.map(([title,text],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${text}</p></li>`).join('')}</ol>`;
const faqs=items=>`<div class="m-faq-list">${items.map(([question,answer])=>`<details><summary>${question}${icon('plus')}</summary><p>${answer}</p></details>`).join('')}</div>`;
const cta=(title='Better partnerships start with a clear next step.')=>`<section class="m-closing container"><span class="eyebrow">FOUR DEDICATED PORTALS</span><h2>${title}</h2><p>Choose the account and tools that match your work.</p><div class="m-actions">${[['Brand','brand'],['Creator','creator'],['Affiliate','affiliate'],['Agency','agency']].map(([name,id])=>button('Start as '+(id==='affiliate'||id==='agency'?'an ':'a ')+name.toLowerCase(),'/auth/'+id+'/signup',id==='brand'?'dark':'white')).join('')}</div></section>`;

function contactSection(options={},standalone=false){
 const draft=options.contactDraft||{},value=(name,max)=>escape(typeof draft[name]==='string'?draft[name].slice(0,max):''),reference=typeof options.contactReference==='string'&&/^[0-9a-f-]{36}$/i.test(options.contactReference)?options.contactReference:null;
 const heading=standalone?'h1':'h2';
 return `<section class="m-section container m-contact-section" id="contact"><div class="m-contact-copy"><span class="eyebrow">CONTACT AFFIMARO</span><${heading}>A question?<br><em>Let’s talk.</em></${heading}><p>Tell us what you need help with. From your first application to your website connection, your message goes to the Affimaro team.</p><div class="m-contact-routes"><a href="/help"><strong>Looking for a quick answer?</strong><span>Explore the help center ${icon('arrow')}</span></a><a href="/integrations"><strong>Connecting your website?</strong><span>Find the guide for your platform ${icon('arrow')}</span></a></div><p class="m-contact-note">For a brand’s program decision or commission payment, contact that business through your partnership.</p></div><div class="m-contact-panel">${reference?`<div class="m-contact-receipt" role="status"><span class="eyebrow">MESSAGE RECEIVED</span><h2>Thank you for getting in touch.</h2><p>Your message has been received. Our team will review it.</p><a class="text-link" href="/contact">Send another message ${icon('arrow')}</a></div>`:`<form class="m-contact-form" data-contact-form action="/api/contact" method="post"><input type="hidden" name="id" value="${value('id',36)}"><div class="m-contact-fields"><label for="contact-name">Your name<input id="contact-name" name="name" autocomplete="name" required minlength="2" maxlength="100" value="${value('name',100)}"></label><label for="contact-email">Email address<input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="254" value="${value('email',254)}"></label></div><label for="contact-topic">How can we help?<select id="contact-topic" name="topic" required>${contactTopics.map(topic=>`<option value="${topic.id}"${draft.topic===topic.id?' selected':''}>${topic.label}</option>`).join('')}</select></label><label for="contact-message">Your message<textarea id="contact-message" name="message" rows="6" required minlength="20" maxlength="4000" aria-describedby="contact-message-help">${value('message',4000)}</textarea></label><small id="contact-message-help">Include the relevant page or platform and what happened. Please leave out passwords, API keys, card numbers and bank details.</small><div class="m-contact-trap" aria-hidden="true"><label for="contact-fax">Leave this field empty<input id="contact-fax" name="fax" tabindex="-1" autocomplete="off" maxlength="200" value=""></label></div><p class="m-contact-feedback" data-contact-feedback role="status" aria-live="polite"${options.contactError?' data-state="error"':''}>${options.contactError?escape(options.contactError):''}</p><button class="btn btn-dark" type="submit">Send message ${icon('arrow')}</button><p class="m-contact-note">Your name, email and message are used to handle your enquiry. Read our <a href="/data-and-privacy">data &amp; privacy overview</a>.</p></form>`}</div></section>`;
}


const wordpressLoginForm=(error='')=>`<form class="m-wordpress-login" action="/integrations/wordpress-admin" method="get" target="_blank" rel="noopener noreferrer">${error?`<p class="m-contact-feedback" data-state="error" role="alert">${escape(error)}</p>`:''}<label for="wordpress-home">Your WordPress installation URL<input id="wordpress-home" name="website" type="url" required maxlength="300" placeholder="https://yourstore.com" autocomplete="url" aria-describedby="wordpress-login-help"></label><button type="submit" class="text-link">Open WordPress admin ${icon('arrow-up')}</button><small id="wordpress-login-help">Include its installation folder if needed. Opens your own site in a new tab.</small></form>`;
function platformCards(detailed=false){
 return `<div class="m-platform-grid">${storePlatforms.map(p=>`<article class="m-platform-card"><div class="m-platform-card-heading"><span class="m-platform-mark" aria-hidden="true">${escape(p.mark)}</span><div><h3>${p.loginUrl?`<a href="${escape(p.loginUrl)}" target="_blank" rel="noopener noreferrer">${escape(p.name)}</a>`:escape(p.name)}</h3><span>${escape(p.capability)}</span></div></div><p>${escape(detailed?p.setupNote:p.description)}</p>${p.id==='woocommerce'?wordpressLoginForm():''}<div class="m-platform-actions">${p.loginUrl?`<a class="text-link" href="${escape(p.loginUrl)}" target="_blank" rel="noopener noreferrer">Sign in to ${escape(p.name)} ${icon('arrow-up')}</a>`:''}<a class="text-link" href="${p.guideUrl}">Setup guide ${icon('arrow')}</a></div></article>`).join('')}</div>`;
}
const platformOverview=(detailed=false)=>`${intro('CONNECT YOUR WEBSITE','Your platform.<br>A clear path to connect.','For brands and authorized agency programs. Open your platform’s admin, then complete its setup in Affimaro. Affiliates and creators share their approved links without connecting a store.')}${platformCards(detailed)}<div class="m-platform-footnote"><p>Signing in opens your platform account. Your website becomes connected after its Affimaro setup is verified. BigCommerce, Wix and Squarespace require a developer, API/event access and your own backend.</p><a class="text-link" href="/contact">Need help choosing? Contact us ${icon('arrow')}</a></div>`;

