const guides={
  'brand-start':{title:'Launch your first partner program',eyebrow:'FOR BRANDS',text:'A practical starting point for a brand account, from business details to your first verified referred order.',steps:[['Create and verify your brand account','Create your brand login and verify your email. Complete the business, website, audience and program profile, then submit it to the Affimaro owner. Your brand portal opens only after approval.'],['Review your program rules','Check the commission rate and attribution window in Program settings. Save the rules you want new referrals to use.'],['Connect your website','Choose WooCommerce, Shopify or Custom website in Store settings. Follow its guide and verify the connection.'],['Invite your first affiliate','Share the program application link. The affiliate creates their own account and explicitly applies. Review the application in your brand dashboard.'],['Test an order and refund','Use an approved link on a staging website. Compare order, commission and refund records in both portals before wider use.']],action:['Open brand sign in','/auth/brand/login']},
  'affiliate-start':{title:'Your first brand invitation',eyebrow:'FOR AFFILIATES',text:'Start with your own affiliate account and a brand’s program invitation. A brand subscription is not required.',steps:[['Create and verify your affiliate account','Create your affiliate login and verify your email. Complete your channels, audience, experience and promotion strategy, then submit your profile for owner review. Your affiliate portal opens only after approval.'],['Open a brand’s invitation','Use the application link the brand shares. Check the business website, rate and attribution window.'],['Review before applying','Saving a profile does not send an application. Choose Apply to this program when you are ready to share your profile with that business.'],['Wait for the brand’s decision','Your application page and affiliate portal show the current status. An approved referral link appears when the program and verified store are active.'],['Follow your own results','Use your approved link and inspect your referred orders and commission. Available earnings depend on eligibility, refunds and brand approval.']],action:['Open affiliate sign in','/auth/affiliate/login']},
  payments:{title:'Understand commission and payment records',eyebrow:'FOR BOTH SIDES',text:'Keep three ideas distinct: commission estimated from orders, commission approved by the brand, and an actual payment.',steps:[['Read the order state','Eligible processing/completed orders may accrue commission. Pending payment has no accrued commission; refunds can reduce or reverse it.'],['Review approval and availability','The brand approves earned commission. An available balance accounts for reservations, payments and later refund adjustments.'],['Create a supported request','The affiliate requests available approved commission to a saved bank destination or an eligible Stripe receiving account.'],['Pay directly and record accurately','The brand makes a bank/Wise transfer outside Affimaro and records its completion, or explicitly confirms a supported USD Stripe transfer.'],['Check the final record','A request is not proof of settlement. Bank records are entered by the brand. Verified Stripe transfers confirm connected-account credit; subsequent bank payout is separate.']],action:['Read payment setup','/downloads/payments-setup.md']},
};
guides['woocommerce-setup']={title:'Connect your WooCommerce store',eyebrow:'WOOCOMMERCE CONNECTION GUIDE',text:'Follow these steps in your WordPress store and your own Affimaro brand or agency account.',steps:[['Open your store settings','In a brand account, open Program & assets → Program & store settings → Store. In an agency account, open Agency tools → Represented program → Store. Select WooCommerce.'],['Create the connection','Enter your store’s exact HTTPS home URL. Include its subdirectory when applicable. Save the displayed Affimaro URL, connection ID and one-time signing key securely.'],['Install the WordPress plugin','Download the Affimaro WooCommerce plugin ZIP from the Store page. In WordPress, open Plugins → Add New → Upload Plugin, upload the ZIP and activate it with WooCommerce enabled.'],['Save and verify','Open WooCommerce → Affimaro in WordPress. Paste the Affimaro URL, connection ID and signing key from your own account. Save the settings and run Test connection. Keep the signing key private.'],['Check an order and refund','Use an approved partner’s tracked link on a staging store. Allow referral tracking, complete a test order and check its commission in Affimaro. Test partial and full refunds before sharing links widely. If delivery fails, review the plugin’s status and retry the affected order.']],action:['WooCommerce integration & plugin','/integrations/woocommerce']};
guides['shopify-setup']={title:'Connect your Shopify store',eyebrow:'SHOPIFY CONNECTION GUIDE',text:'Connect your merchant-owned app, verify the store and import eligible order updates from your Affimaro dashboard.',steps:[['Open your store settings','In a brand account, open Program & assets → Program & store settings → Store. In an agency account, open Agency tools → Represented program → Store. Select Shopify.'],['Prepare your merchant-owned app','Use an app and store in the same Shopify organization. Grant read_orders and install the app on that store. This connection uses the merchant-owned app workflow.'],['Verify the connection in Affimaro','Enter your store’s .myshopify.com domain and the app’s client ID and client secret in the Shopify connection form. Select Verify and connect Shopify. Credentials stay in the private account connection.'],['Complete dashboard sync','Select Sync Shopify orders. If more orders remain, continue sync until the batch finishes. This connection refreshes when you run sync; changes do not arrive automatically in the background.'],['Review attribution and refunds','Test an approved partner’s referral link and a staging checkout. Native conversion information may cover up to 30 days. Complete a recent sync before reviewing commission or recording a payment, and test refunds as well.']],action:['Shopify integration overview','/integrations/shopify']};
guides['custom-website-setup']={title:'Connect your own website',eyebrow:'CUSTOM WEBSITE CONNECTION GUIDE',text:'For websites with their own backend. Your developer connects referral sessions and verified order updates to your program.',steps:[['Choose Custom website','Open your represented program’s Store settings and select Custom website. Enter the exact HTTPS home URL, including a subdirectory when applicable.'],['Save the connection details','Give the displayed Affimaro URL, connection ID and one-time signing key to your backend developer. Keep the signing key in server-side secret settings.'],['Add the server integration','Download the Affimaro server client. Your developer implements trusted referral sessions, order/payment checks and reliable delivery of signed order and refund updates.'],['Run the connection test','Use the connection test from your backend and check that Affimaro marks the connection verified. A saved URL alone does not complete setup.'],['Verify a checkout and refund','Follow an approved partner’s tracked link on a staging website. Verify the order and commission record, then test partial and full refunds. Resolve any delivery errors before publishing links widely.']],action:['Custom website integration & client','/integrations/custom']};
