marketingPages['/resources']={title:'Guides & resources | Affimaro',description:'Setup guides for brands, affiliates, creators and agencies, plus website connections and commission workflows.',active:'resources',body:`<section class="m-page-hero container"><span class="eyebrow">RESOURCE CENTER</span><h1>Less guessing.<br><em>A clearer next step.</em></h1><p>Understand the workflow, choose the right connection and get your own account ready to use.</p></section><section class="m-section container">${featureCards([['store','Start a brand program','Business setup, program rules, store verification and your first approved affiliate.','/guides/brand-start'],['users','Start as an affiliate','Your account, a program invitation, approval and your first referral link.','/guides/affiliate-start'],['pointer','Start as a creator','Your channels, reviewed partnerships and private content planner.','/guides/creator-start'],['chart','Start as an agency','Your reviewed agency profile, client directory and authorized represented program.','/guides/agency-start'],['wallet','Understand commission','What estimated, approved, reserved and recorded payment amounts mean.','/guides/payments']])}</section><section class="m-section m-tinted"><div class="container">${intro('PUT YOUR SETUP IN CONTEXT','The right guide<br>for your connection.','Read the setup guide for your platform, then return to your account to connect your store.')}<div class="m-downloads">${Object.entries(integrationData).map(([key,c])=>`<a href="/integrations/${key}"><strong>${c.name}</strong><span>Requirements, setup and downloads${icon('arrow')}</span></a>`).join('')}<a href="/downloads/reports-guide.md"><strong>Reports and CSV exports</strong><span>Report definitions and exact monetary values${icon('arrow')}</span></a><a href="/install"><strong>Install the web app</strong><span>Android, iPhone and desktop instructions${icon('arrow')}</span></a></div></div></section>${cta()}`};
marketingPages['/help']={
 title:'Help center | Affimaro',
 description:'Help for brand, affiliate, creator and agency accounts: profile review, channel verification, partnerships, click reports, commission and account settings.',
 active:'resources',
 body:`<section class="m-page-hero container"><span class="eyebrow">HELP CENTER</span><h1>A little clarity<br><em>goes a long way.</em></h1><p>Find answers for your brand, affiliate, creator or agency account, then follow the guide that fits your next step.</p></section>
<section class="m-section container m-help">${faqs([
 ['Does verifying my email approve my account?','No. Brands, affiliates, creators and agencies complete their own profile, verify the websites or channels they list and submit an application for Affimaro owner review. Check Application status for decisions or requests for more information. Email confirmation alone does not open a portal.'],
 ['Which account should I create?','Choose Brand to run your business’s partner program, Affiliate to promote participating brands, Creator for partnerships and a private content planner, or Agency for a client directory and the represented program you are authorized to manage. Affiliate and creator accounts are free; brands and agencies use a paid package.'],
 ['Can I switch roles inside my account?','Each account has one primary role, with its own onboarding, navigation and permissions. There is no role switch inside a real portal. Use a separate account and email if you need another role. An agency client-directory entry does not grant access to that client’s account or create another program.'],
 ['How do I verify a website or social channel?','Open Channels & ownership and add the exact property you control. Websites can use the displayed DNS TXT record. For a public-code review, place the current verification code on the claimed website or channel and submit a proof URL for owner review. Saving a URL or sending evidence does not itself verify ownership.'],
 ['How do I find and manage partnerships?','Approved affiliates and creators can find participating brands in Discover and follow applications and invitations in My brands. Brands and agencies find eligible affiliates and creators, then manage applications and invitations in My partners. Directory visibility is optional. Accepting an invitation sends an application for business review; it does not automatically approve membership.'],
 ['Where are brand assets and coupon codes?','Approved partners can open the materials shared with their partnership. A business can share an asset or code with all approved partners or assign it to one partner. Publishing a coupon in Affimaro does not create the discount in the merchant’s store; the business must configure and test it there.'],
 ['Why is an approved referral link missing?','The partnership must remain approved, the program must be active, and its website connection must be active and verified. The business running the program controls those settings. Account approval alone does not activate every brand partnership.'],
 ['What do click reports measure?','The Clicks view reports requests recorded through Affimaro tracked referral links, with UTC dates and available source, device and country information for the most recent 90 days. A click is not proof of a unique person, purchase or earned commission. Older direct store links are not measured by this report.'],
 ['Why has an order not appeared?','Confirm the program website’s setup, referral eligibility and delivery status. Shopify needs a dashboard sync. Custom websites need their developer’s server session and event-delivery implementation. Affiliates and creators use approved links; they do not connect a store to receive referred-order records.'],
 ['Why is commission different after a refund?','Commission uses eligible net merchandise. Partial refunds reduce that amount; full refunds or cancellations reverse commission. An unresolved allocation holds commission for review. The business approves eligible earnings before they become available for a payment request.'],
 ['Does a payment request mean money was sent?','No. A request reserves approved commission. The business reviews it and pays through a supported method. Bank and Wise transfers take place outside Affimaro and are recorded here. Follow the resulting payment record; a request alone does not confirm settlement.'],
 ['Who should I contact about an application or payment?','For your Affimaro profile application, check the owner’s messages on Application status. For membership in a specific program or its commission payments, contact the business running that program through its linked website. The Affimaro owner’s profile review and a business’s partner review are separate decisions. Affimaro does not hold partner funds.'],
 ['Where can I change my theme and preferences?','Open Settings in your own portal. Appearance offers Light, Dark and Use device setting. The other sections cover your profile, report and link preferences, reminders, discovery privacy, security and the tools for your role. Save changes to keep them on your account.'],
 ['Can I close my account?','Open the Close account option in your account settings. Confirm your identity and resolve any listed subscription, order, commission or payment blockers first. Closure ends access and sessions and removes the profile from discovery. It retains financial and review history; it does not reverse a payment or erase those records.'],
 ['Can I use Affimaro on my phone?','Yes. Install the web app from a supported browser and sign in with your existing account. Your account and financial records need a live connection.'],
 ['Does a package payment need a second approval?','No. Profile review happens once. After approval, brands and agencies can go directly to package checkout. Brand plans are Starter $19, Growth $49 and Business $99 USD per month. Agency plans are Starter $39, Growth $79 and Business $149 USD per month; affiliate and creator accounts are free. Selecting a package alone does not charge a card. Subscription payment confirmation is separate from a business’s review of partner commission.'],
 ['Can I explore without creating an account?','Yes. The four portal previews use fictional examples and browser-local actions. You can explore the navigation and settings without signing up. Preview activity does not create a real application, order or payment.'],
])}<div class="m-actions">${button('Explore all guides','/resources')}${button('Preview all four portals','/preview','outline')}${button('Integration setup','/integrations','outline')}</div></section>${cta()}`
};
marketingPages['/about']={title:'About Affimaro',description:'Affimaro is an independent affiliate-management platform, built around clearer programs and dedicated partner portals.',active:'resources',body:`<section class="m-page-hero container"><span class="eyebrow">ABOUT AFFIMARO</span><h1>Good partnerships<br><em>deserve a clear home.</em></h1><p>Affimaro gives brands, affiliates, creators and agencies dedicated spaces for their part of a partnership, connected by referral, order and commission records.</p></section><section class="m-section container m-detail-band"><div><span class="eyebrow">WHY WE ARE BUILDING IT</span><h2>Make the work<br>easier to understand.</h2><p>Brands need to review partners and understand referred orders and commission. Affiliates need clear links and earnings records. Creators need a place for their channels and content plans. Agencies need client records and a defined scope for the program they represent.</p><p>Affimaro is built around those practical needs. Each role has its own account, navigation and tools, with access limited to the records that belong to it.</p></div><div class="m-callout"><h3>What guides the product</h3><ul><li>Separate roles and account permissions</li><li>Explainable commission and refund records</li><li>Store connections with explicit verification</li><li>Payment review before money movement</li><li>Clear descriptions of what is available now</li></ul></div></section><section class="m-section m-tinted"><div class="container">${intro('THE CURRENT CHAPTER','An independent product.<br>A focused pilot.','The current release supports one website and one program per brand or agency account, alongside dedicated affiliate and creator portals. Real store setup and payment-provider availability depend on each business’s own configuration.')}<div class="m-actions">${button('Explore the platform','/platform')}${button('View current packages','/pricing','white')}</div></div></section>${cta()}`};
marketingPages['/contact']={title:'Contact Affimaro',description:'Get in touch with Affimaro about your account, website connection, subscription or partnership enquiry.',active:'contact',body:contactSection({},true)};

marketingPages['/data-and-privacy']={title:'Data & privacy overview | Affimaro',description:'Understand what Affimaro records, which side can see it, and how account and payment information is scoped.',active:'resources',body:`<article class="container m-guide"><header><span class="eyebrow">DATA & PRIVACY OVERVIEW</span><h1>Your records.<br>A defined purpose.</h1><p>A practical overview of the current product’s data flows and access boundaries.</p></header><section><h2>Application review</h2><p>Brand, affiliate, creator and agency applicants submit contact details, public website/channel URLs, business or audience information and a promotion strategy for the Affimaro owner to review. This application is private to the applicant and authorized owner. It is not a public directory profile. Review decisions and messages appear on the applicant’s status page. No identity documents or bank details are requested in this application. Creator content and agency client-directory records are not public. The account owner manages them; authorized Affimaro platform administration can inspect operational records for service oversight. A directory entry never grants another brand’s account permissions.</p><h2>Contact messages</h2><p>The contact form records your name, email address, chosen topic and message in a private owner inbox. We use these details to handle your enquiry. Contact submissions also keep hashed email and network identifiers to limit abuse; raw network addresses are not stored with the message. Your email address may also receive a short numbered acknowledgement. This is a service confirmation and does not subscribe you to marketing. Do not include passwords, API keys, payment card numbers or bank details.</p><h2>Account and profile information</h2><p>Affimaro uses your verified identity and saved profile to identify your account. Affiliate profile details are shared with a brand when you choose to apply to that brand’s program. Passwords are not part of the profile shared with a business.</p><h2>Program, referral and order records</h2><p>Brands manage their own programs and connected store records. Affiliates see their own applications, eligible referral links and referred order/commission records. Account permissions are checked on the server.</p><h2>Bank and provider settings</h2><p>Bank destinations and provider credentials are protected server-side and are not included in public pages or report exports. Saved bank/provider secrets use encryption. Relevant payment details are disclosed only within the authorized payment workflow.</p><h2>Payment responsibility</h2><p>Each business funds its own affiliate payments. Bank/Wise payment records are entered by the business. Supported Stripe transfers use the business’s provider connection and explicit review. Affimaro does not hold affiliate funds or store customer card numbers.</p><h2>Device-local examples</h2><p>The separate demo dashboards use synthetic sample data stored in that browser. Demo edits do not create a real account, order or payment. Installed-app caching is limited to public assets and the reconnect page; private account and financial data require a live connection.</p><h2>Understand the workflow before sharing</h2><p>Use the application and connection guides to review what each action records. Contact a program’s business through its linked website for questions about that business’s applications or payment records.</p></section><div class="m-actions">${button('Read the help center','/help','outline')}</div><section><h2>Optional directory visibility</h2><p>Approved members can opt in to share reviewed business or display details and verified public property links with other approved members. Contact details, registration fields, review notes and bank information are excluded from these listings.</p></section><section><h2>Outbound link click reports</h2><p>Affimaro tracked referral links record the partnership, UTC time, reported campaign source and medium, referring hostname when supplied, broad device category and country code when available. Visitor IP addresses, full referring URLs and raw user-agent strings are not stored. Reports cover the most recent 90 days; older events are removed in batches as tracked links are used. Click events do not establish a purchase, unique person or earned commission. Previously shared direct store links are not measured by this redirect report.</p></section><section><h2>Partner materials</h2><p>Brand assets and coupon codes are scoped to approved partnerships. Brands choose whether a resource is shared with every approved partner or one assigned partner. Affimaro publishes store coupon details without creating the discount in the store.</p></section></article>`};
const accountTypes=[
 {id:'brand',path:'/brands',home:'/workspace',label:'Brands & advertisers',title:'Your brand. Your program.',text:'Run your own program, review partners, connect your website and manage commission.'},
 {id:'creator',path:'/creators',home:'/creator',label:'Creators & influencers',title:'Your content. Relevant partners.',text:'Present your channels, plan content and follow approved partnerships and earnings.'},
 {id:'affiliate',path:'/affiliates',home:'/partner',label:'Affiliate partners',title:'Your reach. A clearer record.',text:'Manage publishing properties, program applications, referral links and commission.'},
 {id:'agency',path:'/agencies',home:'/agency',label:'Agencies',title:'Your clients. A clearer workflow.',text:'Keep a private client directory and manage the represented brand program approved for your account.'}
];
const planOptions=planCatalog;
function portalChoiceBody(signup,plan,returnTo){
 const selected=Object.hasOwn(planOptions,plan||'')?plan:null;
 let continuation=null;try{if(typeof returnTo==='string'&&returnTo.length<=500&&returnTo.startsWith('/')&&!returnTo.startsWith('//')){const u=new URL(returnTo,'https://app.local');if(u.origin==='https://app.local'&&!u.pathname.startsWith('/auth/'))continuation=u.pathname+u.search+u.hash;}}catch{}
 return `<section class="m-page-hero container m-portal-choice-heading"><span class="eyebrow">${signup&&selected?'BRAND &amp; AGENCY SUBSCRIPTION · STEP 1 OF 3':signup?'CHOOSE YOUR ACCOUNT':'WELCOME BACK'}</span><h1>Four ways to work.<br><em>A portal of your own.</em></h1><p>Brands, creators, affiliate partners and agencies each have their own registration, profile, navigation and dashboard. All accounts require email verification and owner review.</p>${selected?`<div class="m-callout"><h2>${planOptions[selected].name} package</h2><p>Choose your account type below to see its monthly price. First sign in or create your account, then complete account review. After approval, continue to secure payment. Creator and affiliate accounts are free.</p></div>`:''}</section><section class="container m-section"><div class="m-audience-paths">${accountTypes.map(a=>{const paid=a.id==='brand'||a.id==='agency',next=accountReturnTo(a.id,continuation||(selected&&paid?(a.id==='agency'?'/agency/billing':'/billing')+'?plan='+selected:a.home)),href='/auth/'+a.id+'/'+(signup?'signup':'login')+((selected&&paid)||continuation?'?'+(selected&&paid?'plan='+selected+'&':'')+'return_to='+encodeURIComponent(next):'');return `<article><span class="eyebrow">${a.label.toUpperCase()}</span><h3>${a.title}</h3><span class="m-account-price">${paid?(selected?plansForRole(a.id)[selected].name+' · $'+plansForRole(a.id)[selected].amount+' USD / month':'From $'+plansForRole(a.id).starter.amount+' USD / month'):'Free · no subscription'}</span><p>${a.text}</p>${button(signup?(paid?'Create '+a.id+' account':'Create free '+a.id+' account'):a.id[0].toUpperCase()+a.id.slice(1)+' sign in',href)}${signup&&selected&&paid?`<a class="text-link" href="/auth/${a.id}/login?plan=${selected}&amp;return_to=${encodeURIComponent(next)}">Already have an account? Sign in ${icon('arrow')}</a>`:''}<a href="${a.path}">Explore ${a.label.toLowerCase()} ${icon('arrow')}</a></article>`;}).join('')}</div></section><section class="container m-choice-note"><p>Each account has one primary role. Use a separate account and email if you need another role. Your saved records and access remain with their original account.</p></section>`;
}
for(const kind of ['login','get-started'])marketingPages['/'+kind]={title:(kind==='login'?'Log in':'Get started')+' | Affimaro',description:'Choose your own brand, creator, affiliate or agency account.',active:'',body:portalChoiceBody(kind==='get-started')};
marketingPages['/creators']={title:'Creators & influencers | Affimaro',description:'A dedicated creator studio for channels, content planning, reviewed partnerships and commission.',active:'creators',body:`<section class="m-page-hero container"><span class="eyebrow">FOR CREATORS & INFLUENCERS</span><h1>Your content.<br><em>Relevant partners.</em></h1><p>Bring your creative identity and public channels into your own creator account. Plan your next post, apply to invited programs and keep recorded earnings in view.</p><div class="m-actions">${button('Create a creator account','/auth/creator/signup')}${button('Explore the creator demo','/demo/creators','white')}</div><a class="text-link m-hero-login" href="/auth/creator/login">Creator sign in ${icon('arrow')}</a></section><section class="m-section container">${intro('YOUR CREATOR STUDIO','A space for<br>the work you create.','Creator access is free. Your dashboard and navigation stay separate from the affiliate publisher portal.')}${featureCards([['users','Your channel profile','Share your main platform, public portfolio, formats, publishing rhythm and audience for owner review.','/guides/creator-start'],['check','Your content planner','Save ideas and drafts, attach one of your approved partnerships and add the URL when content is published.','/features/creator-studio'],['link','Your partnerships & earnings','Find approved referral links, review recorded orders and request eligible approved commission.','/guides/payments']])}</section><section class="m-section m-tinted"><div class="container">${intro('A REVIEWED START','From your profile<br>to your next partnership.','Affimaro approval opens your creator studio. A brand separately decides whether to accept you into its program.')}${steps([['Create your creator account','Verify your email, complete your creator profile and submit it to the owner.'],['Apply to an invited program','Review the brand’s rules and send your application. Approval is never automatic.'],['Plan, share and follow','Keep your content plan private. Share approved links and follow the orders and commission recorded by the brand.']])}</div></section><section class="m-section container"><div class="m-callout"><h2>Keep the workflow clear.</h2><p>The planner records your ideas, notes and public content URLs. It does not publish to social networks or promise a sponsorship. Brand commission follows eligible referred sales and the brand’s own review.</p><p>Creator accounts are free. A recorded order, an approved commission and a completed payment are separate steps.</p></div></section>${cta()}`};
marketingPages['/agencies']={title:'Agency workspace | Affimaro',description:'A dedicated agency portal for your reviewed profile, client directory and represented partner program.',active:'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">FOR AGENCIES</span><h1>Your clients.<br><em>A clearer workflow.</em></h1><p>Bring your agency identity, business contacts and represented partner program into your own agency account. Keep the client directory separate from each brand’s account permissions.</p><div class="m-actions">${button('Create an agency account','/auth/agency/signup')}${button('Explore the agency demo','/demo/agencies','white')}</div><a class="text-link m-hero-login" href="/auth/agency/login">Agency sign in ${icon('arrow')}</a></section><section class="m-section container">${intro('YOUR OWN AGENCY PORTAL','A directory. A program.<br>A defined responsibility.','Apply with your agency details, services, experience and the business you are authorized to represent.')}${featureCards([['users','Client directory','Save business contacts, engagement status and private notes in your agency workspace.','/features/agency-directory'],['store','Represented program','Manage the approved brand’s partner applications, program rules and connected website.','/guides/agency-start'],['chart','Program reporting','Review scoped order, commission and payment records without opening another account’s data.','/features/reporting']])}</section><section class="m-section m-tinted"><div class="container">${intro('A PRACTICAL FIRST ENGAGEMENT','Your agency.<br>Your represented brand.','All packages include one connected website, one program and one account owner. Package capacity controls approved program partners and client-directory records.')}${steps([['Apply as an agency','Verify your email, complete the agency and represented-brand details and select your package.'],['Complete owner review','Approval opens your own agency portal with its client directory and represented program.'],['Manage within the agreed scope','Review program partners, connected orders and commission. Keep other client contacts in the directory.']])}</div></section><section class="m-section container"><div class="m-callout"><h2>A client contact is not an account permission.</h2><p>Adding a client does not connect its store, grant access to another brand or create a second program. This release manages one represented brand program per agency account. Each business remains responsible for its affiliate payments.</p><a class="text-link" href="/pricing?for=agency">Choose your agency package ${icon('arrow')}</a></div></section>${cta()}`};
for(const [id,title,items] of [
 ['creator-start','Start with your creator studio',[['Create the right account','Choose Creator on Get started. Verify your email and complete your channels, formats, public portfolio and audience details.'],['Wait for the owner’s review','Your portal opens only after approval. Review messages appear on your application page.'],['Build your partnerships','Open a brand invitation and explicitly apply. The brand separately reviews this program membership.'],['Plan and record your content','Save ideas, drafts and published links in your private planner. Attaching a partnership does not publish content or create commission.']]],
 ['agency-start','Start with your agency workspace',[['Apply as an agency','Choose Agency, provide your business details and confirm your authority to represent the listed brand. Select a package before submitting.'],['Complete owner review','Your agency profile and represented-brand details are reviewed before access opens.'],['Organize your directory','Save client contacts, status and private notes. A directory record does not create an account permission or connect another store.'],['Manage your represented program','Use the one connected website and program approved for this agency account. Review partners, referred orders and commission within that scope.']]]
])marketingPages['/guides/'+id]={title:title+' | Affimaro',description:title,active:'resources',body:`<article class="container m-guide"><header><span class="eyebrow">SETUP GUIDE</span><h1>${title}</h1></header>${items.map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<div class="m-actions">${button('Create '+(id==='creator-start'?'creator':'agency')+' account','/auth/'+(id==='creator-start'?'creator':'agency')+'/signup')}${button('Account sign in','/auth/'+(id==='creator-start'?'creator':'agency')+'/login','outline')}</div></article>`};
for(const [id,title,body,role] of [
 ['creator-studio','A private workspace for your content.','Plan ideas and drafts, add public URLs and attach one of your approved program partnerships. The creator studio keeps your own notes and content separate from order and commission records.','creator'],
 ['agency-directory','A directory for your client relationships.','Store client contact details, business websites, engagement status and private notes. Records stay with the agency account. A directory entry never creates access to another brand’s program or connects another website.','agency']
])marketingPages['/features/'+id]={title:title+' | Affimaro',description:body,active:role==='creator'?'creators':'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">${role.toUpperCase()} TOOLS</span><h1>${title}</h1><p>${body}</p><div class="m-actions">${button('Create '+role+' account','/auth/'+role+'/signup')}${button('View '+role+' demo','/demo/'+(role==='creator'?'creators':'agencies'),'white')}</div></section>`};
for(const role of ['creator','agency'])marketingPages['/demo/'+(role==='creator'?'creators':'agencies')]={title:role[0].toUpperCase()+role.slice(1)+' demo | Affimaro',description:'An illustrative '+role+' portal preview with synthetic content.',active:role==='creator'?'creators':'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">${role.toUpperCase()} DEMO · ILLUSTRATIVE SAMPLE</span><h1>${role==='creator'?'Your content.<br><em>A studio of your own.</em>':'Your agency.<br><em>A clearer workspace.</em>'}</h1><p>Synthetic sample content. This preview does not read or change any live account, application, order or payment.</p><div class="m-actions">${button('Create '+role+' account','/auth/'+role+'/signup')}${button(role[0].toUpperCase()+role.slice(1)+' sign in','/auth/'+role+'/login','white')}</div></section><section class="m-section container">${role==='creator'?featureCards([['users','Channel profile','Example: video tutorials · weekly publishing · creator portfolio.','/guides/creator-start'],['check','Content planner','Example idea: a product walkthrough. Save drafts and published links in your real creator studio.','/features/creator-studio'],['link','Reviewed partnerships','Real links and earnings appear only after program approval and eligible recorded referrals.','/guides/payments']]):featureCards([['users','Client directory','Example client: Sample Studio · prospect. Your real agency directory stores contacts and private notes.','/features/agency-directory'],['store','Represented program','One connected brand program is managed within the account’s approved scope.','/guides/agency-start'],['chart','Scoped reports','Live reports use only the represented program’s recorded results.','/features/reporting']])}</section>`};
for(const page of Object.values(marketingPages)){
 page.body=page.body.replaceAll('Two dedicated portals.','Four dedicated portals.').replaceAll('Brand and affiliate portals have separate entry points, navigation and account permissions.','Brand, creator, affiliate and agency portals have separate registration, navigation and account permissions.').replaceAll('Brand, affiliate, creator and agency applicants','Brand, affiliate, creator and agency applicants').replaceAll('Growth and Business are planned and unavailable for purchase. Affiliate accounts are free to use.','Approved brands and agencies can purchase all three packages directly. Creator and affiliate accounts are free to use.').replaceAll('Starter describes current capabilities; paid checkout is not open yet.','Every package has defined capacity. Selecting a package does not start a charge.');
}

export function renderMarketingDocument(path,sprite,options={}){
  if(!Object.hasOwn(marketingPages,path))return null;
  const original=marketingPages[path],page=['/login','/get-started'].includes(path)?{...original,body:portalChoiceBody(path==='/get-started',options.plan,options.returnTo)}:path==='/contact'?{...original,body:contactSection(options,true)}:path==='/integrations/wordpress-admin'?{...original,body:wordpressLoginBody(options.wordpressError)}:original,install=`<a class="corner-install" href="/install" aria-label="Install Affimaro on your device">${icon('download')}<span>Install app</span></a>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#153b32"><title>${escape(page.title)}</title><meta name="description" content="${escape(page.description)}"><link rel="icon" href="/demo/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/demo/styles.css"><link rel="stylesheet" href="/marketing.css"><script src="/marketing-nav.js" defer></script>${['/','/contact'].includes(path)?'<script src="/contact-form.js" defer></script>':''}</head><body class="marketing-page">${sprite}<a class="skip-link" href="#main">Skip to content</a>${marketingHeader(page.active)}<main id="main" tabindex="-1">${page.body}</main>${marketingFooter()}${install}</body></html>`;
}
